import 'dart:convert';

/// User preferences that can be serialised to and from JSON.
class Settings {
  /// Creates a set of settings.
  const Settings({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
    this.locale = 'en',
  });

  /// The account name. Never empty.
  final String username;

  /// The preferred font size, within `8..72`.
  final int fontSize;

  /// Whether the dark colour scheme is selected.
  final bool darkMode;

  /// Free-form labels. No element is empty.
  final List<String> tags;

  /// The language tag, as two lowercase letters optionally followed by an
  /// underscore and two uppercase letters, such as `en` or `de_DE`.
  final String locale;

  /// Returns a JSON-encodable representation of these settings.
  Map<String, Object?> toJson() {
    return <String, Object?>{
      'username': username,
      'fontSize': fontSize,
      'darkMode': darkMode,
      'tags': List<String>.of(tags),
      'locale': locale,
    };
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) {
      return true;
    }
    return other is Settings &&
        other.username == username &&
        other.fontSize == fontSize &&
        other.darkMode == darkMode &&
        other.locale == locale &&
        _sameTags(other.tags, tags);
  }

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags), locale);

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags, locale: $locale)';

  static bool _sameTags(List<String> a, List<String> b) {
    if (identical(a, b)) {
      return true;
    }
    if (a.length != b.length) {
      return false;
    }
    for (var i = 0; i < a.length; i++) {
      if (a[i] != b[i]) {
        return false;
      }
    }
    return true;
  }
}

/// Thrown when a JSON document cannot be read as a [Settings].
class SettingsFormatException implements Exception {
  /// Creates an exception describing why parsing failed.
  const SettingsFormatException(this.message);

  /// A human readable description that names the offending key, if any.
  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// Parses [json] into a [Settings].
///
/// Throws a [SettingsFormatException] if the text is not a JSON object, if a
/// required key is missing, or if a value has the wrong type or is out of
/// range. No other exception escapes this function.
Settings parseSettings(String json) {
  final Object? decoded;
  try {
    decoded = jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException('invalid JSON: ${error.message}');
  }

  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException(
      'the top level value must be a JSON object',
    );
  }

  return Settings(
    username: _readUsername(decoded),
    fontSize: _readFontSize(decoded),
    darkMode: _readDarkMode(decoded),
    tags: _readTags(decoded),
    locale: _readLocale(decoded),
  );
}

String _readUsername(Map<String, Object?> map) {
  const key = 'username';
  if (!map.containsKey(key)) {
    throw const SettingsFormatException('missing required key "$key"');
  }
  final value = map[key];
  if (value is! String) {
    throw const SettingsFormatException('"$key" must be a string');
  }
  if (value.isEmpty) {
    throw const SettingsFormatException('"$key" must not be empty');
  }
  return value;
}

int _readFontSize(Map<String, Object?> map) {
  const key = 'fontSize';
  final value = map[key];
  if (value == null) {
    return 14;
  }
  final int size;
  if (value is int) {
    size = value;
  } else if (value is double && value == value.roundToDouble()) {
    size = value.toInt();
  } else {
    throw const SettingsFormatException('"$key" must be an integer');
  }
  if (size < 8 || size > 72) {
    throw const SettingsFormatException('"$key" must be within 8..72');
  }
  return size;
}

bool _readDarkMode(Map<String, Object?> map) {
  const key = 'darkMode';
  final value = map[key];
  if (value == null) {
    return false;
  }
  if (value is! bool) {
    throw const SettingsFormatException('"$key" must be a boolean');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> map) {
  const key = 'tags';
  final value = map[key];
  if (value == null) {
    return const <String>[];
  }
  if (value is! List<Object?>) {
    throw const SettingsFormatException('"$key" must be a list of strings');
  }
  final tags = <String>[];
  for (final element in value) {
    if (element is! String) {
      throw const SettingsFormatException('"$key" must contain only strings');
    }
    if (element.isEmpty) {
      throw const SettingsFormatException(
        '"$key" must not contain an empty string',
      );
    }
    tags.add(element);
  }
  return List<String>.unmodifiable(tags);
}

/// Matches a language tag such as `en` or `de_DE`, and nothing else.
final RegExp _localePattern = RegExp(r'^[a-z]{2}(_[A-Z]{2})?$');

String _readLocale(Map<String, Object?> map) {
  const key = 'locale';
  final value = map[key];
  if (value == null) {
    return 'en';
  }
  if (value is! String) {
    throw const SettingsFormatException('"$key" must be a string');
  }
  if (!_localePattern.hasMatch(value)) {
    throw const SettingsFormatException(
      '"$key" must be two lowercase letters, optionally followed by an '
      'underscore and two uppercase letters',
    );
  }
  return value;
}

import 'dart:async';

import 'package:flutter/material.dart';

/// Counts down from [duration] to zero, one second at a time.
///
/// The object that creates a controller owns it and is responsible for
/// calling [dispose]; widgets that render it never do.
class CountdownController extends ChangeNotifier {
  CountdownController({required Duration duration})
    : _duration = duration,
      _remaining = duration;

  static const Duration _tick = Duration(seconds: 1);

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  /// Time left before the countdown reaches zero.
  Duration get remaining => _remaining;

  /// Whether the countdown is currently ticking down.
  bool get isRunning => _timer != null;

  /// Starts ticking. Does nothing while running or once [remaining] is zero.
  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, _onTick);
    notifyListeners();
  }

  /// Stops ticking, keeping [remaining]. Does nothing when not running.
  void pause() {
    if (!isRunning) {
      return;
    }
    _cancelTimer();
    notifyListeners();
  }

  /// Adds [extra] to [remaining], notifying listeners once.
  ///
  /// A running countdown keeps ticking from the new value; a paused or
  /// finished one stays stopped, so [start] picks it up again.
  ///
  /// Throws an [ArgumentError] when [extra] is zero or negative, leaving the
  /// countdown untouched.
  void addTime(Duration extra) {
    if (extra <= Duration.zero) {
      throw ArgumentError.value(extra, 'extra', 'must be greater than zero');
    }
    _remaining += extra;
    notifyListeners();
  }

  /// Stops ticking and restores [remaining] to the original duration.
  void reset() {
    _cancelTimer();
    _remaining = _duration;
    notifyListeners();
  }

  void _onTick(Timer timer) {
    if (_remaining <= _tick) {
      _remaining = Duration.zero;
      _cancelTimer();
    } else {
      _remaining -= _tick;
    }
    notifyListeners();
  }

  void _cancelTimer() {
    _timer?.cancel();
    _timer = null;
  }

  @override
  void dispose() {
    _cancelTimer();
    super.dispose();
  }
}

/// Shows the remaining time of a [CountdownController] as `mm:ss` alongside
/// start, pause, reset and add-ten-seconds buttons.
class CountdownTimer extends StatefulWidget {
  const CountdownTimer({required this.controller, super.key, this.onFinished});

  /// The countdown to display and drive. Owned by the caller.
  final CountdownController controller;

  /// Called once each time the countdown reaches zero.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  static const Duration _extraTime = Duration(seconds: 10);

  bool _finishedNotified = false;

  @override
  void initState() {
    super.initState();
    _attach(widget.controller);
  }

  @override
  void didUpdateWidget(covariant CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_onControllerChanged);
      _attach(widget.controller);
    }
  }

  @override
  void dispose() {
    // The controller belongs to the caller, so only the listener goes away.
    widget.controller.removeListener(_onControllerChanged);
    super.dispose();
  }

  void _attach(CountdownController controller) {
    // An already finished controller must not fire [onFinished] again.
    _finishedNotified = controller.remaining == Duration.zero;
    controller.addListener(_onControllerChanged);
  }

  void _onControllerChanged() {
    setState(() {});
    final bool finished = widget.controller.remaining == Duration.zero;
    if (finished && !_finishedNotified) {
      _finishedNotified = true;
      widget.onFinished?.call();
    } else if (!finished) {
      _finishedNotified = false;
    }
  }

  static String _format(Duration remaining) {
    final String minutes = remaining.inMinutes.toString().padLeft(2, '0');
    final String seconds = (remaining.inSeconds % 60).toString().padLeft(
      2,
      '0',
    );
    return '$minutes:$seconds';
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        Text(_format(widget.controller.remaining)),
        Row(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            TextButton(
              onPressed: widget.controller.start,
              child: const Text('Start'),
            ),
            TextButton(
              onPressed: widget.controller.pause,
              child: const Text('Pause'),
            ),
            TextButton(
              onPressed: widget.controller.reset,
              child: const Text('Reset'),
            ),
            TextButton(
              onPressed: () => widget.controller.addTime(_extraTime),
              child: const Text('+10s'),
            ),
          ],
        ),
      ],
    );
  }
}

import 'dart:async';

import 'package:flutter/material.dart';

const _oneSecond = Duration(seconds: 1);
const _tenSeconds = Duration(seconds: 10);

class CountdownController extends ChangeNotifier {
  new({required this._duration}) : _remaining = _duration;

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  Duration get remaining => _remaining;

  bool get isRunning => _timer != null;

  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_oneSecond, _tick);
  }

  void pause() {
    if (!isRunning) {
      return;
    }
    _stop();
    notifyListeners();
  }

  void reset() {
    _stop();
    _remaining = _duration;
    notifyListeners();
  }

  void addTime(Duration extra) {
    if (extra <= Duration.zero) {
      throw ArgumentError.value(extra, 'extra', 'must be greater than zero');
    }
    _remaining += extra;
    notifyListeners();
  }

  @override
  void dispose() {
    _stop();
    super.dispose();
  }

  void _stop() {
    _timer?.cancel();
    _timer = null;
  }

  void _tick(Timer timer) {
    final next = _remaining - _oneSecond;
    _remaining = next > Duration.zero ? next : Duration.zero;
    if (_remaining == Duration.zero) {
      _stop();
    }
    notifyListeners();
  }
}

class CountdownTimer extends StatefulWidget {
  const new({required this.controller, this.onFinished, super.key});

  final CountdownController controller;
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  var _finished = false;

  @override
  void initState() {
    super.initState();
    _finished = widget.controller.remaining == Duration.zero;
    widget.controller.addListener(_handleUpdate);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleUpdate);
      widget.controller.addListener(_handleUpdate);
      _finished = widget.controller.remaining == Duration.zero;
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleUpdate);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Column(
    mainAxisSize: MainAxisSize.min,
    children: [
      Text(_formatted(widget.controller.remaining)),
      Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          TextButton(
            onPressed: widget.controller.start,
            child: const Text('Start'),
          ),
          TextButton(
            onPressed: widget.controller.pause,
            child: const Text('Pause'),
          ),
          TextButton(
            onPressed: widget.controller.reset,
            child: const Text('Reset'),
          ),
          TextButton(
            onPressed: () => widget.controller.addTime(_tenSeconds),
            child: const Text('+10s'),
          ),
        ],
      ),
    ],
  );

  String _formatted(Duration value) {
    final minutes = value.inMinutes.toString().padLeft(2, '0');
    final seconds = (value.inSeconds % Duration.secondsPerMinute)
        .toString()
        .padLeft(2, '0');
    return '$minutes:$seconds';
  }

  void _handleUpdate() {
    final hasFinished = widget.controller.remaining == Duration.zero;
    final justFinished = hasFinished && !_finished;
    setState(() {
      _finished = hasFinished;
    });
    if (justFinished) {
      widget.onFinished?.call();
    }
  }
}

import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the latest search.
enum SearchStatus { idle, loading, success, error }

/// Runs debounced searches through a [SearchFetcher] and exposes their state.
class SearchModel extends ChangeNotifier {
  SearchModel({
    required SearchFetcher fetcher,
    Duration debounce = const Duration(milliseconds: 300),
  }) : _runSearch = fetcher,
       _debounceDuration = debounce;

  final SearchFetcher _runSearch;
  final Duration _debounceDuration;

  Timer? _timer;
  bool _disposed = false;

  /// Identifies the search a pending timer or an in-flight fetch belongs to.
  ///
  /// Bumped whenever the query changes or the model is disposed, so that
  /// anything started for an earlier query can be recognised and dropped.
  int _generation = 0;

  SearchStatus _status = SearchStatus.idle;
  String _query = '';
  List<String> _results = const <String>[];
  Object? _error;

  SearchStatus get status => _status;

  String get query => _query;

  List<String> get results => _results;

  Object? get error => _error;

  /// Records [text] as the current query and schedules a fetch for it.
  ///
  /// The fetch runs once the debounce has elapsed without another change.
  /// Text equal to the current query is ignored.
  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }

    _query = text;
    _timer?.cancel();
    _timer = null;
    // Anything already scheduled or in flight belongs to an older query.
    _generation++;

    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
      notifyListeners();
      return;
    }

    final int generation = _generation;
    _timer = Timer(_debounceDuration, () {
      _timer = null;
      unawaited(_fetch(text, generation));
    });
    notifyListeners();
  }

  /// Re-runs the fetch for the current query straight away.
  ///
  /// Only takes effect while [status] is [SearchStatus.error]; the debounce is
  /// skipped, so the status becomes [SearchStatus.loading] before this returns.
  void retry() {
    if (_disposed || _status != SearchStatus.error) {
      return;
    }

    _timer?.cancel();
    _timer = null;
    // Supersede anything scheduled or in flight for the previous attempt.
    _generation++;
    unawaited(_fetch(_query, _generation));
  }

  Future<void> _fetch(String text, int generation) async {
    if (_disposed || generation != _generation) {
      return;
    }

    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();

    try {
      final List<String> results = await _runSearch(text);
      if (_disposed || generation != _generation) {
        return;
      }
      _status = SearchStatus.success;
      _results = List<String>.unmodifiable(results);
      _error = null;
    } on Object catch (error) {
      if (_disposed || generation != _generation) {
        return;
      }
      _status = SearchStatus.error;
      _results = const <String>[];
      _error = error;
    }
    notifyListeners();
  }

  @override
  void notifyListeners() {
    if (_disposed) {
      return;
    }
    super.notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    _generation++;
    super.dispose();
  }
}

import 'dart:convert';

import 'package:flutter/foundation.dart';

const _defaultFontSize = 14;
const _minFontSize = 8;
const _maxFontSize = 72;
const _defaultLocale = 'en';

/// Two lowercase letters, optionally followed by `_` and two uppercase ones.
final _localePattern = RegExp(r'^[a-z]{2}(?:_[A-Z]{2})?$');

@immutable
class Settings {
  const new({
    required this.username,
    this.fontSize = _defaultFontSize,
    this.darkMode = false,
    this.tags = const [],
    this.locale = _defaultLocale,
  });

  final String username;
  final int fontSize;
  final bool darkMode;
  final List<String> tags;
  final String locale;

  Map<String, Object?> toJson() => {
    'username': username,
    'fontSize': fontSize,
    'darkMode': darkMode,
    'tags': tags,
    'locale': locale,
  };

  @override
  bool operator ==(Object other) =>
      other is Settings &&
      other.username == username &&
      other.fontSize == fontSize &&
      other.darkMode == darkMode &&
      listEquals(other.tags, tags) &&
      other.locale == locale;

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags), locale);

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags, locale: $locale)';
}

class SettingsFormatException implements Exception {
  const new(this.message);

  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

Settings parseSettings(String json) {
  final Object? document;
  try {
    document = jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException(
      'The text is not valid JSON: ${error.message}',
    );
  }
  if (document is! Map<String, Object?>) {
    throw const SettingsFormatException(
      'The top level of the document must be a JSON object.',
    );
  }
  return Settings(
    username: _readUsername(document),
    fontSize: _readFontSize(document),
    darkMode: _readDarkMode(document),
    tags: _readTags(document),
    locale: _readLocale(document),
  );
}

String _readUsername(Map<String, Object?> json) {
  final value = json['username'];
  if (value is! String || value.isEmpty) {
    throw const SettingsFormatException(
      'Expected a non-empty string for key: username',
    );
  }
  return value;
}

int _readFontSize(Map<String, Object?> json) {
  if (!json.containsKey('fontSize')) {
    return _defaultFontSize;
  }
  final value = json['fontSize'];
  if (value is! num || !value.isFinite) {
    throw const SettingsFormatException(
      'Expected a whole number for key: fontSize',
    );
  }
  final fontSize = value.toInt();
  if (fontSize != value) {
    throw const SettingsFormatException(
      'Expected a whole number for key: fontSize',
    );
  }
  if (fontSize < _minFontSize || fontSize > _maxFontSize) {
    throw const SettingsFormatException(
      'Expected $_minFontSize..$_maxFontSize for key: fontSize',
    );
  }
  return fontSize;
}

bool _readDarkMode(Map<String, Object?> json) {
  if (!json.containsKey('darkMode')) {
    return false;
  }
  final value = json['darkMode'];
  if (value is! bool) {
    throw const SettingsFormatException('Expected a boolean for key: darkMode');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> json) {
  if (!json.containsKey('tags')) {
    return const [];
  }
  final value = json['tags'];
  if (value is! List<Object?>) {
    throw const SettingsFormatException(
      'Expected a list of non-empty strings for key: tags',
    );
  }
  final tags = <String>[];
  for (final tag in value) {
    if (tag is! String || tag.isEmpty) {
      throw const SettingsFormatException(
        'Expected a list of non-empty strings for key: tags',
      );
    }
    tags.add(tag);
  }
  return tags;
}

String _readLocale(Map<String, Object?> json) {
  if (!json.containsKey('locale')) {
    return _defaultLocale;
  }
  final value = json['locale'];
  if (value is! String || !_localePattern.hasMatch(value)) {
    throw const SettingsFormatException(
      'Expected a code such as en or de_DE for key: locale',
    );
  }
  return value;
}

import 'dart:async';

import 'package:flutter/foundation.dart';

typedef SearchFetcher = Future<List<String>> Function(String query);

enum SearchStatus { idle, loading, success, error }

class SearchModel extends ChangeNotifier {
  new({
    required this._fetcher,
    this._debounce = const Duration(milliseconds: 300),
  });

  final SearchFetcher _fetcher;
  final Duration _debounce;

  var _status = SearchStatus.idle;
  var _query = '';
  var _results = const <String>[];
  Object? _error;
  Timer? _debounceTimer;
  var _fetchId = 0;
  var _isDisposed = false;

  SearchStatus get status => _status;

  String get query => _query;

  List<String> get results => _results;

  Object? get error => _error;

  void onQueryChanged(String text) {
    if (_isDisposed || text == _query) {
      return;
    }
    _query = text;
    _debounceTimer?.cancel();
    _debounceTimer = null;
    // Whatever is in flight belongs to an older query, so its response is
    // stale from here on.
    _fetchId++;
    if (text.isEmpty) {
      // Nothing to fetch.
      _status = SearchStatus.idle;
      _results = const [];
      _error = null;
      notifyListeners();
      return;
    }
    notifyListeners();
    _debounceTimer = Timer(_debounce, _startFetch);
  }

  void retry() {
    if (_isDisposed || _status != SearchStatus.error) {
      return;
    }
    // The user asked for this one, so it skips the debounce.
    _debounceTimer?.cancel();
    _startFetch();
  }

  @override
  void dispose() {
    _isDisposed = true;
    _debounceTimer?.cancel();
    _debounceTimer = null;
    super.dispose();
  }

  void _startFetch() {
    _debounceTimer = null;
    if (_isDisposed) {
      return;
    }
    _status = SearchStatus.loading;
    notifyListeners();
    unawaited(_fetch(++_fetchId, _query));
  }

  Future<void> _fetch(int fetchId, String query) async {
    try {
      final results = await _fetcher(query);
      if (_isDisposed || fetchId != _fetchId) {
        return;
      }
      _results = List.unmodifiable(results);
      _error = null;
      _status = SearchStatus.success;
    } on Object catch (error) {
      if (_isDisposed || fetchId != _fetchId) {
        return;
      }
      _results = const [];
      _error = error;
      _status = SearchStatus.error;
    }
    notifyListeners();
  }
}

import 'dart:async';

import 'package:flutter/material.dart';

/// Counts down from [duration] to zero, one second at a time.
///
/// The object that creates the controller owns it and is responsible for
/// calling [dispose]; a [CountdownTimer] using it will never dispose it.
class CountdownController extends ChangeNotifier {
  CountdownController({required Duration duration})
    : _duration = duration,
      _remaining = duration;

  static const Duration _tick = Duration(seconds: 1);

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  /// The time left before the countdown finishes.
  ///
  /// Starts out at the `duration` the controller was created with.
  Duration get remaining => _remaining;

  /// Whether the countdown is currently ticking down.
  bool get isRunning => _timer != null;

  /// Starts ticking.
  ///
  /// Does nothing when the countdown is already running or has finished.
  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, (_) => _onTick());
  }

  /// Stops ticking, keeping [remaining] where it is.
  ///
  /// Does nothing when the countdown is not running.
  void pause() {
    if (!isRunning) {
      return;
    }
    _cancel();
    notifyListeners();
  }

  /// Adds [extra] to [remaining], notifying listeners once.
  ///
  /// Works while running, in which case ticking carries on from the new
  /// value, while paused, and after the countdown has finished, in which
  /// case [remaining] becomes [extra] and [start] runs it again.
  ///
  /// Throws an [ArgumentError] when [extra] is not positive, leaving the
  /// countdown untouched.
  void addTime(Duration extra) {
    if (extra <= Duration.zero) {
      throw ArgumentError.value(extra, 'extra', 'must be greater than zero');
    }
    _remaining += extra;
    notifyListeners();
  }

  /// Stops ticking and puts [remaining] back to the original duration.
  void reset() {
    _cancel();
    _remaining = _duration;
    notifyListeners();
  }

  void _onTick() {
    final Duration next = _remaining - _tick;
    if (next <= Duration.zero) {
      _remaining = Duration.zero;
      _cancel();
    } else {
      _remaining = next;
    }
    notifyListeners();
  }

  void _cancel() {
    _timer?.cancel();
    _timer = null;
  }

  @override
  void dispose() {
    _cancel();
    super.dispose();
  }
}

/// Displays the [controller]'s remaining time and controls for it.
class CountdownTimer extends StatefulWidget {
  const CountdownTimer({required this.controller, super.key, this.onFinished});

  /// The countdown to display. Owned by the caller, never disposed here.
  final CountdownController controller;

  /// Called once, when the countdown reaches zero.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  bool _finished = false;

  @override
  void initState() {
    super.initState();
    widget.controller.addListener(_onChanged);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_onChanged);
      widget.controller.addListener(_onChanged);
      _finished = false;
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_onChanged);
    super.dispose();
  }

  void _onChanged() {
    if (!mounted) {
      return;
    }
    setState(() {});
    if (widget.controller.remaining != Duration.zero) {
      // Time was put back on the clock, so zero can be reached again.
      _finished = false;
    } else if (!_finished) {
      _finished = true;
      widget.onFinished?.call();
    }
  }

  static String _format(Duration remaining) {
    final int totalSeconds = remaining.inSeconds;
    final String minutes = '${totalSeconds ~/ 60}'.padLeft(2, '0');
    final String seconds = '${totalSeconds % 60}'.padLeft(2, '0');
    return '$minutes:$seconds';
  }

  @override
  Widget build(BuildContext context) {
    final CountdownController controller = widget.controller;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        Text(_format(controller.remaining)),
        Row(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            TextButton(onPressed: controller.start, child: const Text('Start')),
            TextButton(onPressed: controller.pause, child: const Text('Pause')),
            TextButton(onPressed: controller.reset, child: const Text('Reset')),
            TextButton(
              onPressed: () => controller.addTime(const Duration(seconds: 10)),
              child: const Text('+10s'),
            ),
          ],
        ),
      ],
    );
  }
}

import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The lifecycle of the search for the current query.
enum SearchStatus { idle, loading, success, error }

/// Debounced search over a [SearchFetcher], exposed as a [ChangeNotifier].
class SearchModel extends ChangeNotifier {
  factory SearchModel({
    required SearchFetcher fetcher,
    Duration debounce = const Duration(milliseconds: 300),
  }) => SearchModel._(fetcher, debounce);

  SearchModel._(this._fetcher, this._debounce);

  final SearchFetcher _fetcher;
  final Duration _debounce;

  Timer? _timer;
  bool _disposed = false;

  /// Identifies the newest fetch; responses carrying an older id are stale.
  int _requestId = 0;

  SearchStatus _status = SearchStatus.idle;
  String _query = '';
  List<String> _results = const <String>[];
  Object? _error;

  SearchStatus get status => _status;

  String get query => _query;

  List<String> get results => List<String>.unmodifiable(_results);

  Object? get error => _error;

  void onQueryChanged(String text) {
    if (_disposed || text == _query) return;

    _query = text;
    _timer?.cancel();
    _timer = null;
    // Any response still in flight belongs to an older query now.
    _requestId++;

    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
      notifyListeners();
      return;
    }

    notifyListeners();
    _timer = Timer(_debounce, () {
      _timer = null;
      _start(text);
    });
  }

  /// Re-runs the fetch for the current query, skipping the debounce.
  ///
  /// Does nothing unless [status] is [SearchStatus.error].
  void retry() {
    if (_disposed || _status != SearchStatus.error) return;

    // A pending debounce would only repeat the fetch we are about to start.
    _timer?.cancel();
    _timer = null;
    _start(_query);
  }

  Future<void> _start(String text) async {
    if (_disposed) return;

    final id = ++_requestId;
    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();

    try {
      final fetched = await _fetcher(text);
      if (_disposed || id != _requestId) return;
      _status = SearchStatus.success;
      _results = List<String>.of(fetched);
      _error = null;
    } catch (e) {
      if (_disposed || id != _requestId) return;
      _status = SearchStatus.error;
      _results = const <String>[];
      _error = e;
    }
    notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

import 'dart:async';

import 'package:flutter/material.dart';

/// Drives a countdown that ticks once a second and notifies on every tick.
///
/// The object that creates the controller owns it and is responsible for
/// disposing it; a widget handed one never does.
class CountdownController extends ChangeNotifier {
  new({required this._duration}) : _remaining = _duration;

  final Duration _duration;
  Duration _remaining;
  Timer? _timer;

  Duration get remaining => _remaining;

  bool get isRunning => _timer != null;

  /// Starts ticking. Does nothing while already running or at zero.
  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(const Duration(seconds: 1), _tick);
    notifyListeners();
  }

  /// Stops ticking and keeps the remaining time. Does nothing when stopped.
  void pause() {
    if (!isRunning) {
      return;
    }
    _stop();
    notifyListeners();
  }

  /// Stops ticking and restores the duration the controller was built with.
  void reset() {
    _stop();
    _remaining = _duration;
    notifyListeners();
  }

  /// Adds [extra] to the remaining time, whether running, paused or finished.
  ///
  /// Ticking is unaffected: a running countdown continues from the new value,
  /// and a finished one is left stopped with [extra] remaining, ready for
  /// another [start]. Throws an `ArgumentError` when [extra] is not positive.
  void addTime(Duration extra) {
    if (extra <= Duration.zero) {
      throw ArgumentError.value(extra, 'extra', 'must be greater than zero');
    }
    _remaining += extra;
    notifyListeners();
  }

  @override
  void dispose() {
    _stop();
    super.dispose();
  }

  void _tick(Timer timer) {
    const second = Duration(seconds: 1);
    _remaining = _remaining > second ? _remaining - second : Duration.zero;
    if (_remaining == Duration.zero) {
      _stop();
    }
    notifyListeners();
  }

  void _stop() {
    _timer?.cancel();
    _timer = null;
  }
}

/// Shows the controller's remaining time as `mm:ss` with transport buttons.
class CountdownTimer extends StatefulWidget {
  const new({required this.controller, this.onFinished, super.key});

  final CountdownController controller;

  /// Called once each time the countdown reaches zero while mounted.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  late bool _finished;

  @override
  void initState() {
    super.initState();
    // A controller that is already at zero has finished before this widget
    // existed, so it must not fire the callback again.
    _finished = widget.controller.remaining == Duration.zero;
    widget.controller.addListener(_handleChange);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleChange);
      _finished = widget.controller.remaining == Duration.zero;
      widget.controller.addListener(_handleChange);
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleChange);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final controller = widget.controller;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Text(_format(controller.remaining)),
        Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            TextButton(onPressed: controller.start, child: const Text('Start')),
            TextButton(onPressed: controller.pause, child: const Text('Pause')),
            TextButton(onPressed: controller.reset, child: const Text('Reset')),
            TextButton(onPressed: _addTime, child: const Text('+10s')),
          ],
        ),
      ],
    );
  }

  void _addTime() => widget.controller.addTime(const Duration(seconds: 10));

  void _handleChange() {
    if (!mounted) {
      return;
    }
    setState(() {});
    final reachedZero = widget.controller.remaining == Duration.zero;
    if (!reachedZero) {
      // A reset (or a fresh controller) arms the callback again.
      _finished = false;
      return;
    }
    if (!_finished) {
      _finished = true;
      widget.onFinished?.call();
    }
  }

  String _format(Duration value) {
    final minutes = value.inMinutes.toString().padLeft(2, '0');
    final seconds = (value.inSeconds % Duration.secondsPerMinute)
        .toString()
        .padLeft(2, '0');
    return '$minutes:$seconds';
  }
}

import 'dart:convert';

/// User preferences that can be serialised to and from JSON.
class Settings {
  const Settings({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
    this.locale = 'en',
  });

  /// Display name of the user. Never empty.
  final String username;

  /// Editor font size, always within [minFontSize]..[maxFontSize].
  final int fontSize;

  /// Whether the dark colour scheme is active.
  final bool darkMode;

  /// Free-form labels. Individual tags are never empty.
  final List<String> tags;

  /// Language tag, always matching [localePattern].
  final String locale;

  /// Smallest accepted value for [fontSize].
  static const int minFontSize = 8;

  /// Largest accepted value for [fontSize].
  static const int maxFontSize = 72;

  /// The shape of an accepted [locale]: two lowercase ASCII letters, followed
  /// by an optional underscore and two uppercase ASCII letters.
  static final RegExp localePattern = RegExp(r'^[a-z]{2}(?:_[A-Z]{2})?$');

  /// The JSON representation understood by [parseSettings].
  Map<String, Object?> toJson() {
    return <String, Object?>{
      'username': username,
      'fontSize': fontSize,
      'darkMode': darkMode,
      'tags': List<String>.of(tags),
      'locale': locale,
    };
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) {
      return true;
    }
    if (other is! Settings) {
      return false;
    }
    if (other.username != username ||
        other.fontSize != fontSize ||
        other.darkMode != darkMode ||
        other.locale != locale ||
        other.tags.length != tags.length) {
      return false;
    }
    for (var i = 0; i < tags.length; i++) {
      if (other.tags[i] != tags[i]) {
        return false;
      }
    }
    return true;
  }

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags), locale);

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags, locale: $locale)';
}

/// Thrown when a document cannot be turned into a valid [Settings].
class SettingsFormatException implements Exception {
  const SettingsFormatException(this.message);

  /// Human readable explanation naming the offending key, when there is one.
  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// Decodes [json] into [Settings].
///
/// Throws a [SettingsFormatException] if the text is not a JSON object, if a
/// required key is missing, or if a value has the wrong type or is out of
/// range. No other exception escapes this function.
Settings parseSettings(String json) {
  final Object? decoded;
  try {
    decoded = jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException('invalid JSON: ${error.message}');
  } on Object {
    throw const SettingsFormatException('invalid JSON');
  }

  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException(
      'the top level value must be a JSON object',
    );
  }

  return Settings(
    username: _readUsername(decoded),
    fontSize: _readFontSize(decoded),
    darkMode: _readDarkMode(decoded),
    tags: _readTags(decoded),
    locale: _readLocale(decoded),
  );
}

String _readUsername(Map<String, Object?> map) {
  const key = 'username';
  if (!map.containsKey(key)) {
    throw const SettingsFormatException('"$key" is required');
  }
  final value = map[key];
  if (value is! String) {
    throw const SettingsFormatException('"$key" must be a string');
  }
  if (value.isEmpty) {
    throw const SettingsFormatException('"$key" must not be empty');
  }
  return value;
}

int _readFontSize(Map<String, Object?> map) {
  const key = 'fontSize';
  if (!map.containsKey(key)) {
    return 14;
  }
  final value = map[key];
  final int size;
  if (value is int) {
    size = value;
  } else if (value is double &&
      value.isFinite &&
      value == value.roundToDouble()) {
    size = value.toInt();
  } else {
    throw const SettingsFormatException('"$key" must be an integer');
  }
  if (size < Settings.minFontSize || size > Settings.maxFontSize) {
    throw const SettingsFormatException(
      '"$key" must be between ${Settings.minFontSize} and '
      '${Settings.maxFontSize}',
    );
  }
  return size;
}

bool _readDarkMode(Map<String, Object?> map) {
  const key = 'darkMode';
  if (!map.containsKey(key)) {
    return false;
  }
  final value = map[key];
  if (value is! bool) {
    throw const SettingsFormatException('"$key" must be a boolean');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> map) {
  const key = 'tags';
  if (!map.containsKey(key)) {
    return const <String>[];
  }
  final value = map[key];
  if (value is! List) {
    throw const SettingsFormatException('"$key" must be a list of strings');
  }
  final tags = <String>[];
  for (final entry in value) {
    if (entry is! String) {
      throw const SettingsFormatException('"$key" must only contain strings');
    }
    if (entry.isEmpty) {
      throw const SettingsFormatException(
        '"$key" must not contain an empty string',
      );
    }
    tags.add(entry);
  }
  return List<String>.unmodifiable(tags);
}

String _readLocale(Map<String, Object?> map) {
  const key = 'locale';
  if (!map.containsKey(key)) {
    return 'en';
  }
  final value = map[key];
  if (value is! String) {
    throw const SettingsFormatException('"$key" must be a string');
  }
  if (!Settings.localePattern.hasMatch(value)) {
    throw const SettingsFormatException(
      '"$key" must be two lowercase letters, optionally followed by an '
      'underscore and two uppercase letters',
    );
  }
  return value;
}

import 'dart:async';

import 'package:flutter/foundation.dart';

typedef SearchFetcher = Future<List<String>> Function(String query);

enum SearchStatus { idle, loading, success, error }

class SearchModel extends ChangeNotifier {
  new({
    required this._fetcher,
    this._debounce = const Duration(milliseconds: 300),
  });

  final SearchFetcher _fetcher;
  final Duration _debounce;

  /// Bumped by every accepted query change, so a fetch started for an older
  /// query can tell that its result is no longer wanted.
  var _generation = 0;
  var _status = SearchStatus.idle;
  var _query = '';
  var _results = const <String>[];
  Object? _error;
  Timer? _timer;
  var _disposed = false;

  SearchStatus get status => _status;

  String get query => _query;

  List<String> get results => _results;

  Object? get error => _error;

  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }
    _query = text;
    _timer?.cancel();
    _timer = null;
    _generation++;
    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const [];
      _error = null;
    } else {
      final generation = _generation;
      _timer = Timer(_debounce, () => _startFetch(text, generation));
    }
    notifyListeners();
  }

  /// Re-runs the fetch for the current query immediately, skipping the
  /// debounce. Does nothing unless the last fetch ended in an error.
  void retry() {
    if (_disposed || _status != SearchStatus.error) {
      return;
    }
    // A debounced fetch may already be pending for a query typed after the
    // failure; this one replaces it.
    _timer?.cancel();
    _startFetch(_query, _generation);
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }

  void _startFetch(String text, int generation) {
    if (_disposed || generation != _generation) {
      return;
    }
    _timer = null;
    _status = SearchStatus.loading;
    notifyListeners();
    unawaited(_fetch(text, generation));
  }

  Future<void> _fetch(String text, int generation) async {
    try {
      final fetched = await _fetcher(text);
      if (_disposed || generation != _generation) {
        return;
      }
      _results = List.unmodifiable(fetched);
      _error = null;
      _status = SearchStatus.success;
    } on Object catch (error) {
      if (_disposed || generation != _generation) {
        return;
      }
      _results = const [];
      _error = error;
      _status = SearchStatus.error;
    }
    notifyListeners();
  }
}

import 'dart:convert';

import 'package:flutter/foundation.dart';

@immutable
class Settings {
  const new({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
    this.locale = 'en',
  });

  final String username;
  final int fontSize;
  final bool darkMode;
  final List<String> tags;
  final String locale;

  Map<String, Object?> toJson() => {
    'username': username,
    'fontSize': fontSize,
    'darkMode': darkMode,
    'tags': tags,
    'locale': locale,
  };

  @override
  bool operator ==(Object other) =>
      other is Settings &&
      other.username == username &&
      other.fontSize == fontSize &&
      other.darkMode == darkMode &&
      listEquals(other.tags, tags) &&
      other.locale == locale;

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags), locale);

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags, locale: $locale)';
}

class SettingsFormatException implements Exception {
  const new(this.message);

  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

Settings parseSettings(String json) {
  final Object? document;
  try {
    document = jsonDecode(json) as Object?;
  } on FormatException {
    throw const SettingsFormatException('The text is not valid JSON');
  }
  if (document is! Map<String, Object?>) {
    throw const SettingsFormatException(
      'The top level of the document must be a JSON object',
    );
  }
  return Settings(
    username: _readUsername(document),
    fontSize: _readFontSize(document),
    darkMode: _readDarkMode(document),
    tags: _readTags(document),
    locale: _readLocale(document),
  );
}

String _readUsername(Map<String, Object?> json) {
  final value = json['username'];
  if (value is! String) {
    throw const SettingsFormatException('Expected a string for key: username');
  }
  if (value.isEmpty) {
    throw const SettingsFormatException(
      'Expected a non-empty string for key: username',
    );
  }
  return value;
}

int _readFontSize(Map<String, Object?> json) {
  if (!json.containsKey('fontSize')) {
    return 14;
  }
  final value = json['fontSize'];
  // A JSON number reaches Dart as `int` on the VM and as `double` on the web,
  // so the check is on `num` and on the absence of a fractional part.
  if (value is! num || value % 1 != 0) {
    throw const SettingsFormatException(
      'Expected a whole number for key: fontSize',
    );
  }
  final fontSize = value.toInt();
  if (fontSize < 8 || fontSize > 72) {
    throw const SettingsFormatException(
      'Expected a value between 8 and 72 for key: fontSize',
    );
  }
  return fontSize;
}

bool _readDarkMode(Map<String, Object?> json) {
  if (!json.containsKey('darkMode')) {
    return false;
  }
  final value = json['darkMode'];
  if (value is! bool) {
    throw const SettingsFormatException('Expected a boolean for key: darkMode');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> json) {
  if (!json.containsKey('tags')) {
    return const [];
  }
  final value = json['tags'];
  if (value is! List<Object?>) {
    throw const SettingsFormatException(
      'Expected a list of strings for key: tags',
    );
  }
  final tags = <String>[];
  for (final entry in value) {
    if (entry is! String) {
      throw const SettingsFormatException(
        'Expected a list of strings for key: tags',
      );
    }
    if (entry.isEmpty) {
      throw const SettingsFormatException(
        'Expected every entry to be non-empty for key: tags',
      );
    }
    tags.add(entry);
  }
  return List<String>.unmodifiable(tags);
}

// Two lowercase ASCII letters, optionally followed by an underscore and two
// uppercase ASCII letters: `en` and `de_DE`, but not `EN`, `de-DE` or `deu`.
final _localePattern = RegExp(r'^[a-z]{2}(_[A-Z]{2})?$');

String _readLocale(Map<String, Object?> json) {
  if (!json.containsKey('locale')) {
    return 'en';
  }
  final value = json['locale'];
  if (value is! String) {
    throw const SettingsFormatException('Expected a string for key: locale');
  }
  if (!_localePattern.hasMatch(value)) {
    throw const SettingsFormatException(
      'Expected a code such as en or de_DE for key: locale',
    );
  }
  return value;
}

import 'dart:async';

import 'package:flutter/material.dart';

const Duration _tick = Duration(seconds: 1);
const Duration _bonus = Duration(seconds: 10);

/// Counts down from [duration] to zero, one second at a time.
///
/// The countdown is driven by a timer that is owned by this controller and
/// cancelled when the controller is disposed. Listeners are notified on every
/// tick as well as whenever the running state changes.
class CountdownController extends ChangeNotifier {
  /// Creates a controller whose [remaining] starts at [duration].
  CountdownController({required this.duration}) : _remaining = duration;

  /// The value [remaining] starts at and is restored to by [reset].
  final Duration duration;

  Duration _remaining;
  Timer? _timer;

  /// The time left before the countdown finishes.
  Duration get remaining => _remaining;

  /// Whether the countdown is currently ticking.
  bool get isRunning => _timer != null;

  /// Starts ticking.
  ///
  /// Does nothing while already running or when [remaining] is already zero.
  void start() {
    if (isRunning || _remaining <= Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, (_) => _onTick());
    notifyListeners();
  }

  /// Stops ticking, keeping [remaining] where it is.
  ///
  /// Does nothing when not running.
  void pause() {
    if (!isRunning) {
      return;
    }
    _cancel();
    notifyListeners();
  }

  /// Adds [extra] to [remaining], notifying listeners once.
  ///
  /// Ticking is left as it is: a running countdown keeps going from the new
  /// value, and a paused or finished one stays stopped until [start] is called.
  /// Throws an [ArgumentError] when [extra] is not positive, in which case
  /// nothing changes.
  void addTime(Duration extra) {
    if (extra <= Duration.zero) {
      throw ArgumentError.value(extra, 'extra', 'must be greater than zero');
    }
    _remaining = _remaining + extra;
    notifyListeners();
  }

  /// Stops ticking and restores [remaining] to [duration].
  void reset() {
    _cancel();
    _remaining = duration;
    notifyListeners();
  }

  void _onTick() {
    _remaining = _remaining - _tick;
    if (_remaining <= Duration.zero) {
      _remaining = Duration.zero;
      _cancel();
    }
    notifyListeners();
  }

  void _cancel() {
    _timer?.cancel();
    _timer = null;
  }

  @override
  void dispose() {
    _cancel();
    super.dispose();
  }
}

/// Displays the [controller]'s remaining time as `mm:ss` with start, pause,
/// reset and `+10s` buttons.
///
/// The controller is owned by the caller: this widget never disposes it, and
/// the same controller can be handed to another [CountdownTimer] afterwards.
class CountdownTimer extends StatefulWidget {
  /// Creates a countdown display driven by [controller].
  const CountdownTimer({required this.controller, super.key, this.onFinished});

  /// The countdown to display and control.
  final CountdownController controller;

  /// Called once each time the countdown reaches zero.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  late bool _finished;

  @override
  void initState() {
    super.initState();
    _finished = widget.controller.remaining <= Duration.zero;
    widget.controller.addListener(_handleChange);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleChange);
      _finished = widget.controller.remaining <= Duration.zero;
      widget.controller.addListener(_handleChange);
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleChange);
    super.dispose();
  }

  void _handleChange() {
    setState(() {});
    if (widget.controller.remaining > Duration.zero) {
      _finished = false;
      return;
    }
    if (!_finished) {
      _finished = true;
      widget.onFinished?.call();
    }
  }

  void _addBonus() => widget.controller.addTime(_bonus);

  static String _format(Duration remaining) {
    final String minutes = remaining.inMinutes.toString().padLeft(2, '0');
    final String seconds = (remaining.inSeconds % 60).toString().padLeft(
      2,
      '0',
    );
    return '$minutes:$seconds';
  }

  @override
  Widget build(BuildContext context) {
    final CountdownController controller = widget.controller;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        Text(_format(controller.remaining)),
        Row(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            TextButton(onPressed: controller.start, child: const Text('Start')),
            TextButton(onPressed: controller.pause, child: const Text('Pause')),
            TextButton(onPressed: controller.reset, child: const Text('Reset')),
            TextButton(onPressed: _addBonus, child: const Text('+10s')),
          ],
        ),
      ],
    );
  }
}

