import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the latest search.
enum SearchStatus { idle, loading, success, error }

/// Debounces query changes and keeps the results of the latest search.
class SearchModel extends ChangeNotifier {
  SearchModel({
    required this._fetcher,
    this._debounce = const Duration(milliseconds: 300),
  });

  final SearchFetcher _fetcher;
  final Duration _debounce;

  Timer? _timer;
  bool _disposed = false;

  /// Identifies the latest started fetch; responses of any other are stale.
  int _requestId = 0;

  SearchStatus _status = SearchStatus.idle;
  String _query = '';
  List<String> _results = const <String>[];
  Object? _error;

  SearchStatus get status => _status;

  /// The latest text passed to [onQueryChanged].
  String get query => _query;

  List<String> get results => _results;

  /// The error of the latest failed fetch, or `null`.
  Object? get error => _error;

  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }
    _query = text;
    _timer?.cancel();
    _timer = null;

    if (text.isEmpty) {
      // Drop whatever is in flight for an earlier query.
      _requestId++;
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
      notifyListeners();
      return;
    }

    _timer = Timer(_debounce, () {
      _timer = null;
      _startFetch(_query);
    });
    notifyListeners();
  }

  /// Re-runs the fetch for [query] at once, skipping the debounce.
  ///
  /// Does nothing unless [status] is [SearchStatus.error].
  void retry() {
    if (_disposed || _status != SearchStatus.error) {
      return;
    }
    // A pending debounce would only fetch the same query again.
    _timer?.cancel();
    _timer = null;
    _startFetch(_query);
  }

  Future<void> _startFetch(String text) async {
    if (_disposed) {
      return;
    }
    final id = ++_requestId;
    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();

    List<String> fetched;
    try {
      fetched = await _fetcher(text);
    } catch (error) {
      if (_isStale(id, text)) {
        return;
      }
      _status = SearchStatus.error;
      _error = error;
      _results = const <String>[];
      notifyListeners();
      return;
    }

    if (_isStale(id, text)) {
      return;
    }
    _status = SearchStatus.success;
    _error = null;
    _results = List<String>.unmodifiable(fetched);
    notifyListeners();
  }

  /// Whether the response of the fetch [id] for [text] may still be applied.
  ///
  /// A later fetch, or a query change that has not started its fetch yet,
  /// makes an earlier response stale.
  bool _isStale(int id, String text) =>
      _disposed || id != _requestId || text != _query;

  @override
  void notifyListeners() {
    if (_disposed) {
      return;
    }
    super.notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

import 'dart:convert';

/// Thrown when a settings document cannot be parsed into a [Settings].
class SettingsFormatException implements Exception {
  /// Creates an exception describing why parsing failed.
  const SettingsFormatException(this.message);

  /// Human readable description of the problem, naming the offending key.
  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// User preferences for the app.
class Settings {
  /// Creates a settings value.
  const Settings({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
    this.locale = 'en',
  });

  /// Name of the user the settings belong to. Must not be empty.
  final String username;

  /// Editor font size in logical pixels. Must be within `8..72`.
  final int fontSize;

  /// Whether the dark theme is selected.
  final bool darkMode;

  /// Free form labels. Every tag must be non-empty.
  final List<String> tags;

  /// Language tag such as `en` or `de_DE`.
  ///
  /// Two lowercase ASCII letters, optionally followed by an underscore and two
  /// uppercase ASCII letters.
  final String locale;

  /// Converts these settings into a JSON compatible map.
  Map<String, Object?> toJson() => <String, Object?>{
    'username': username,
    'fontSize': fontSize,
    'darkMode': darkMode,
    'tags': List<String>.of(tags),
    'locale': locale,
  };

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) {
      return true;
    }
    return other is Settings &&
        other.username == username &&
        other.fontSize == fontSize &&
        other.darkMode == darkMode &&
        other.locale == locale &&
        _tagsEqual(other.tags, tags);
  }

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags), locale);

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags, locale: $locale)';

  static bool _tagsEqual(List<String> a, List<String> b) {
    if (identical(a, b)) {
      return true;
    }
    if (a.length != b.length) {
      return false;
    }
    for (var i = 0; i < a.length; i++) {
      if (a[i] != b[i]) {
        return false;
      }
    }
    return true;
  }
}

/// Parses [json] into a [Settings].
///
/// Throws a [SettingsFormatException] if the text is not a JSON object, if a
/// required key is missing, or if a value has the wrong type or is out of
/// range. No other exception type escapes this function.
Settings parseSettings(String json) {
  final Object? decoded;
  try {
    decoded = jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException('invalid JSON: ${error.message}');
  }

  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException('top level value must be an object');
  }

  return Settings(
    username: _readUsername(decoded),
    fontSize: _readFontSize(decoded),
    darkMode: _readDarkMode(decoded),
    tags: _readTags(decoded),
    locale: _readLocale(decoded),
  );
}

String _readUsername(Map<String, Object?> map) {
  const key = 'username';
  if (!map.containsKey(key)) {
    throw const SettingsFormatException('missing required key "$key"');
  }
  final value = map[key];
  if (value is! String) {
    throw const SettingsFormatException('"$key" must be a string');
  }
  if (value.isEmpty) {
    throw const SettingsFormatException('"$key" must not be empty');
  }
  return value;
}

int _readFontSize(Map<String, Object?> map) {
  const key = 'fontSize';
  if (!map.containsKey(key)) {
    return 14;
  }
  final value = map[key];
  final int size;
  if (value is int) {
    size = value;
  } else if (value is double &&
      value.isFinite &&
      value == value.roundToDouble()) {
    size = value.toInt();
  } else {
    throw const SettingsFormatException('"$key" must be an integer');
  }
  if (size < 8 || size > 72) {
    throw const SettingsFormatException('"$key" must be within 8..72');
  }
  return size;
}

bool _readDarkMode(Map<String, Object?> map) {
  const key = 'darkMode';
  if (!map.containsKey(key)) {
    return false;
  }
  final value = map[key];
  if (value is! bool) {
    throw const SettingsFormatException('"$key" must be a boolean');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> map) {
  const key = 'tags';
  if (!map.containsKey(key)) {
    return const <String>[];
  }
  final value = map[key];
  if (value is! List<Object?>) {
    throw const SettingsFormatException('"$key" must be a list of strings');
  }
  final tags = <String>[];
  for (final entry in value) {
    if (entry is! String) {
      throw const SettingsFormatException('"$key" must contain only strings');
    }
    if (entry.isEmpty) {
      throw const SettingsFormatException('"$key" entries must not be empty');
    }
    tags.add(entry);
  }
  return List<String>.unmodifiable(tags);
}

/// Matches `en` and `de_DE`, but not `EN`, `de-DE`, `deu` or `de_de`.
final RegExp _localePattern = RegExp(r'^[a-z]{2}(_[A-Z]{2})?$');

String _readLocale(Map<String, Object?> map) {
  const key = 'locale';
  if (!map.containsKey(key)) {
    return 'en';
  }
  final value = map[key];
  if (value is! String) {
    throw const SettingsFormatException('"$key" must be a string');
  }
  if (!_localePattern.hasMatch(value)) {
    throw const SettingsFormatException(
      '"$key" must look like "en" or "de_DE"',
    );
  }
  return value;
}

import 'dart:async';

import 'package:flutter/foundation.dart';

typedef SearchFetcher = Future<List<String>> Function(String query);

enum SearchStatus { idle, loading, success, error }

class SearchModel extends ChangeNotifier {
  new({
    required this._fetcher,
    this._debounce = const Duration(milliseconds: 300),
  });

  final SearchFetcher _fetcher;
  final Duration _debounce;

  Timer? _timer;
  var _status = SearchStatus.idle;
  var _query = '';
  List<String> _results = const [];
  Object? _error;

  /// Identifies the newest request. Every query change bumps it, so a fetch
  /// that started under an older value can no longer win.
  var _requestId = 0;

  var _isDisposed = false;

  SearchStatus get status => _status;

  String get query => _query;

  List<String> get results => _results;

  Object? get error => _error;

  void onQueryChanged(String text) {
    if (_isDisposed || text == _query) {
      return;
    }
    _query = text;
    _requestId++;
    _timer?.cancel();
    _timer = null;
    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const [];
      _error = null;
    } else {
      _timer = Timer(_debounce, _startFetch);
    }
    notifyListeners();
  }

  /// Re-runs the fetch for the current query, skipping the debounce. Only the
  /// error state can be retried; anything else already has a fetch pending or
  /// nothing to repeat.
  void retry() {
    if (_isDisposed || _status != SearchStatus.error) {
      return;
    }
    // A debounce started by a query change made while the error was showing
    // would fetch the same query a second time.
    _timer?.cancel();
    _startFetch();
  }

  void _startFetch() {
    _timer = null;
    if (_isDisposed) {
      return;
    }
    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();
    unawaited(_fetch(_requestId, _query));
  }

  Future<void> _fetch(int requestId, String text) async {
    final List<String> fetched;
    try {
      fetched = await _fetcher(text);
    } on Object catch (error) {
      if (_isDisposed || requestId != _requestId) {
        return;
      }
      _status = SearchStatus.error;
      _error = error;
      _results = const [];
      notifyListeners();
      return;
    }
    if (_isDisposed || requestId != _requestId) {
      return;
    }
    _status = SearchStatus.success;
    _error = null;
    _results = List<String>.unmodifiable(fetched);
    notifyListeners();
  }

  @override
  void dispose() {
    _isDisposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

import 'dart:async';

import 'package:flutter/material.dart';

/// Counts down from [duration] to zero, one second at a time.
///
/// The object that creates a controller owns it and is responsible for
/// calling [dispose]; [CountdownTimer] never disposes the controller it is
/// given.
class CountdownController extends ChangeNotifier {
  CountdownController({required Duration duration})
    : _duration = duration,
      _remaining = duration;

  static const Duration _tick = Duration(seconds: 1);

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  /// The time left before the countdown finishes.
  Duration get remaining => _remaining;

  /// Whether the countdown is currently ticking.
  bool get isRunning => _timer != null;

  /// Starts ticking.
  ///
  /// Does nothing while the countdown is already running or when there is no
  /// time left.
  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, _onTick);
  }

  /// Stops ticking, keeping [remaining] where it is.
  ///
  /// Does nothing when the countdown is not running.
  void pause() {
    if (!isRunning) {
      return;
    }
    _stop();
  }

  /// Adds [extra] to [remaining], notifying listeners once.
  ///
  /// Works while running, in which case ticking carries on from the new
  /// value, while paused, and after the countdown has finished, in which case
  /// [remaining] becomes [extra] and [start] runs the countdown again.
  ///
  /// Throws an [ArgumentError] when [extra] is zero or negative, leaving the
  /// countdown untouched.
  void addTime(Duration extra) {
    if (extra <= Duration.zero) {
      throw ArgumentError.value(extra, 'extra', 'must be greater than zero');
    }
    _remaining += extra;
    notifyListeners();
  }

  /// Stops ticking and sets [remaining] back to the initial duration.
  void reset() {
    _stop();
    _remaining = _duration;
    notifyListeners();
  }

  @override
  void dispose() {
    _stop();
    super.dispose();
  }

  void _onTick(Timer timer) {
    final Duration next = _remaining - _tick;
    if (next <= Duration.zero) {
      _remaining = Duration.zero;
      _stop();
    } else {
      _remaining = next;
    }
    notifyListeners();
  }

  void _stop() {
    _timer?.cancel();
    _timer = null;
  }
}

/// Displays the [controller]'s remaining time as `mm:ss` with start, pause,
/// reset and `+10s` buttons.
class CountdownTimer extends StatefulWidget {
  const CountdownTimer({super.key, required this.controller, this.onFinished});

  /// The countdown to display and drive. Owned by the caller.
  final CountdownController controller;

  /// Called once each time the countdown reaches zero.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  static const Duration _bonus = Duration(seconds: 10);

  bool _finishedReported = false;

  @override
  void initState() {
    super.initState();
    _subscribe(widget.controller);
  }

  @override
  void didUpdateWidget(covariant CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleUpdate);
      _subscribe(widget.controller);
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleUpdate);
    super.dispose();
  }

  void _subscribe(CountdownController controller) {
    _finishedReported = controller.remaining == Duration.zero;
    controller.addListener(_handleUpdate);
  }

  void _handleUpdate() {
    if (!mounted) {
      return;
    }
    setState(() {});
    if (widget.controller.remaining == Duration.zero) {
      if (!_finishedReported) {
        _finishedReported = true;
        widget.onFinished?.call();
      }
    } else {
      _finishedReported = false;
    }
  }

  static String _format(Duration remaining) {
    final String minutes = remaining.inMinutes.toString().padLeft(2, '0');
    final String seconds = (remaining.inSeconds % Duration.secondsPerMinute)
        .toString()
        .padLeft(2, '0');
    return '$minutes:$seconds';
  }

  @override
  Widget build(BuildContext context) {
    final CountdownController controller = widget.controller;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        Text(_format(controller.remaining)),
        Row(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            TextButton(onPressed: controller.start, child: const Text('Start')),
            TextButton(onPressed: controller.pause, child: const Text('Pause')),
            TextButton(onPressed: controller.reset, child: const Text('Reset')),
            TextButton(
              onPressed: () => controller.addTime(_bonus),
              child: const Text('+10s'),
            ),
          ],
        ),
      ],
    );
  }
}

