  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags, locale: $locale)';
}

class SettingsFormatException implements Exception {
  const new(this.message);

  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

Settings parseSettings(String json) {
  final Object? document;
  try {
    document = jsonDecode(json) as Object?;
  } on FormatException {
    throw const SettingsFormatException('The text is not valid JSON');
  }
  if (document is! Map<String, Object?>) {
    throw const SettingsFormatException(
      'The top level of the document must be a JSON object',
    );
  }
  return Settings(
    username: _readUsername(document),
    fontSize: _readFontSize(document),
    darkMode: _readDarkMode(document),
    tags: _readTags(document),
    locale: _readLocale(document),
  );
}

String _readUsername(Map<String, Object?> json) {
  final value = json['username'];
  if (value is! String) {
    throw const SettingsFormatException('Expected a string for key: username');
  }
  if (value.isEmpty) {
    throw const SettingsFormatException(
      'Expected a non-empty string for key: username',
    );
  }
  return value;
}

int _readFontSize(Map<String, Object?> json) {
  if (!json.containsKey('fontSize')) {
    return 14;
  }
  final value = json['fontSize'];
  // A JSON number reaches Dart as `int` on the VM and as `double` on the web,
  // so the check is on `num` and on the absence of a fractional part.
  if (value is! num || value % 1 != 0) {
    throw const SettingsFormatException(
      'Expected a whole number for key: fontSize',
    );
  }
  final fontSize = value.toInt();
  if (fontSize < 8 || fontSize > 72) {
    throw const SettingsFormatException(
      'Expected a value between 8 and 72 for key: fontSize',
    );
  }
  return fontSize;
}

bool _readDarkMode(Map<String, Object?> json) {
  if (!json.containsKey('darkMode')) {
    return false;
  }
  final value = json['darkMode'];
  if (value is! bool) {
    throw const SettingsFormatException('Expected a boolean for key: darkMode');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> json) {
  if (!json.containsKey('tags')) {
    return const [];
  }
  final value = json['tags'];
  if (value is! List<Object?>) {
    throw const SettingsFormatException(
      'Expected a list of strings for key: tags',
    );
  }
  final tags = <String>[];
  for (final entry in value) {
    if (entry is! String) {
      throw const SettingsFormatException(
        'Expected a list of strings for key: tags',
      );
    }
    if (entry.isEmpty) {
      throw const SettingsFormatException(
        'Expected every entry to be non-empty for key: tags',
      );
    }
    tags.add(entry);
  }
  return List<String>.unmodifiable(tags);
}

// Two lowercase letters, optionally followed by `_` and two uppercase ones.
final _localePattern = RegExp(r'^[a-z]{2}(?:_[A-Z]{2})?$');

String _readLocale(Map<String, Object?> json) {
  if (!json.containsKey('locale')) {
    return 'en';
  }
  final value = json['locale'];
  if (value is! String) {
    throw const SettingsFormatException('Expected a string for key: locale');
  }
  if (!_localePattern.hasMatch(value)) {
    throw const SettingsFormatException(
      'Expected a language code such as en or de_DE for key: locale',
    );
  }
  return value;
}

import 'dart:async';

import 'package:flutter/material.dart';

const _tick = Duration(seconds: 1);
const _extra = Duration(seconds: 10);

class CountdownController extends ChangeNotifier {
  new({required this._duration}) : _remaining = _duration;

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  Duration get remaining => _remaining;

  bool get isRunning => _timer != null;

  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, _onTick);
    notifyListeners();
  }

  void pause() {
    if (!isRunning) {
      return;
    }
    _cancel();
    notifyListeners();
  }

  void reset() {
    _cancel();
    _remaining = _duration;
    notifyListeners();
  }

  void addTime(Duration extra) {
    if (extra <= Duration.zero) {
      throw ArgumentError.value(extra, 'extra', 'must be greater than zero');
    }
    _remaining += extra;
    notifyListeners();
  }

  @override
  void dispose() {
    _cancel();
    super.dispose();
  }

  void _onTick(Timer timer) {
    _remaining -= _tick;
    if (_remaining <= Duration.zero) {
      _remaining = Duration.zero;
      _cancel();
    }
    notifyListeners();
  }

  void _cancel() {
    _timer?.cancel();
    _timer = null;
  }
}

class CountdownTimer extends StatefulWidget {
  const new({required this.controller, this.onFinished, super.key});

  final CountdownController controller;
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  late Duration _previous;

  @override
  void initState() {
    super.initState();
    _previous = widget.controller.remaining;
    widget.controller.addListener(_handleChange);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleChange);
      _previous = widget.controller.remaining;
      widget.controller.addListener(_handleChange);
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleChange);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Column(
    mainAxisSize: MainAxisSize.min,
    children: [
      Text(_format(widget.controller.remaining)),
      Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          TextButton(
            onPressed: widget.controller.start,
            child: const Text('Start'),
          ),
          TextButton(
            onPressed: widget.controller.pause,
            child: const Text('Pause'),
          ),
          TextButton(
            onPressed: widget.controller.reset,
            child: const Text('Reset'),
          ),
          TextButton(onPressed: _addTime, child: const Text('+10s')),
        ],
      ),
    ],
  );

  void _addTime() => widget.controller.addTime(_extra);

  void _handleChange() {
    final remaining = widget.controller.remaining;
    final finished = remaining == Duration.zero && _previous > Duration.zero;
    _previous = remaining;
    if (mounted) {
      setState(() {});
    }
    if (finished) {
      widget.onFinished?.call();
    }
  }

  String _format(Duration value) {
    final minutes = value.inMinutes.toString().padLeft(2, '0');
    final seconds = (value.inSeconds % Duration.secondsPerMinute)
        .toString()
        .padLeft(2, '0');
    return '$minutes:$seconds';
  }
}

import 'dart:async';

import 'package:flutter/foundation.dart';

typedef SearchFetcher = Future<List<String>> Function(String query);

enum SearchStatus { idle, loading, success, error }

class SearchModel extends ChangeNotifier {
  new({
    required this._fetcher,
    this._debounce = const Duration(milliseconds: 300),
  });

  final SearchFetcher _fetcher;
  final Duration _debounce;

  Timer? _timer;
  var _status = SearchStatus.idle;
  var _query = '';
  List<String> _results = const [];
  Object? _error;

  /// Identifies the newest request. Every query change bumps it, so a fetch
  /// that started under an older value can no longer win.
  var _requestId = 0;

  var _isDisposed = false;

  SearchStatus get status => _status;

  String get query => _query;

  List<String> get results => _results;

  Object? get error => _error;

  void onQueryChanged(String text) {
    if (_isDisposed || text == _query) {
      return;
    }
    _query = text;
    _requestId++;
    _timer?.cancel();
    _timer = null;
    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const [];
      _error = null;
    } else {
      _timer = Timer(_debounce, _startFetch);
    }
    notifyListeners();
  }

  /// Re-runs the fetch for the current [query] straight away, skipping the
  /// debounce. Does nothing unless [status] is [SearchStatus.error].
  void retry() {
    if (_isDisposed || _status != SearchStatus.error) {
      return;
    }
    _requestId++;
    _timer?.cancel();
    _startFetch();
  }

  void _startFetch() {
    _timer = null;
    if (_isDisposed) {
      return;
    }
    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();
    unawaited(_fetch(_requestId, _query));
  }

  Future<void> _fetch(int requestId, String text) async {
    final List<String> fetched;
    try {
      fetched = await _fetcher(text);
    } on Object catch (error) {
      if (_isDisposed || requestId != _requestId) {
        return;
      }
      _status = SearchStatus.error;
      _error = error;
      _results = const [];
      notifyListeners();
      return;
    }
    if (_isDisposed || requestId != _requestId) {
      return;
    }
    _status = SearchStatus.success;
    _error = null;
    _results = List<String>.unmodifiable(fetched);
    notifyListeners();
  }

  @override
  void dispose() {
    _isDisposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

import 'dart:convert';

import 'package:flutter/foundation.dart';

@immutable
class Settings {
  const new({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
    this.locale = 'en',
  });

  final String username;
  final int fontSize;
  final bool darkMode;
  final List<String> tags;
  final String locale;

  Map<String, Object?> toJson() => {
    'username': username,
    'fontSize': fontSize,
    'darkMode': darkMode,
    'tags': tags,
    'locale': locale,
  };

  @override
  bool operator ==(Object other) =>
      other is Settings &&
      other.username == username &&
      other.fontSize == fontSize &&
      other.darkMode == darkMode &&
      listEquals(other.tags, tags) &&
      other.locale == locale;

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags), locale);

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags, locale: $locale)';
}

class SettingsFormatException implements Exception {
  const new(this.message);

  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

Settings parseSettings(String json) {
  final object = _decodeObject(json);
  return Settings(
    username: _readUsername(object),
    fontSize: _readFontSize(object),
    darkMode: _readDarkMode(object),
    tags: _readTags(object),
    locale: _readLocale(object),
  );
}

const _minFontSize = 8;
const _maxFontSize = 72;

final _localePattern = RegExp(r'^[a-z]{2}(?:_[A-Z]{2})?$');

Never _reject(String key, String expected) =>
    throw SettingsFormatException('Expected $expected for key: $key');

Map<String, Object?> _decodeObject(String source) {
  final Object? decoded;
  try {
    decoded = jsonDecode(source);
  } on FormatException {
    throw const SettingsFormatException('The text is not valid JSON.');
  }
  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException(
      'Expected a JSON object at the top level.',
    );
  }
  return decoded;
}

String _readUsername(Map<String, Object?> json) {
  const key = 'username';
  final value = json[key];
  if (value is! String) {
    _reject(key, 'a string');
  }
  if (value.isEmpty) {
    _reject(key, 'a non-empty string');
  }
  return value;
}

int _readFontSize(Map<String, Object?> json) {
  const key = 'fontSize';
  if (!json.containsKey(key)) {
    return 14;
  }
  final value = json[key];
  if (value is! num || value != value.truncate()) {
    _reject(key, 'an integer');
  }
  final fontSize = value.truncate();
  if (fontSize < _minFontSize || fontSize > _maxFontSize) {
    _reject(key, 'an integer from $_minFontSize to $_maxFontSize');
  }
  return fontSize;
}

bool _readDarkMode(Map<String, Object?> json) {
  const key = 'darkMode';
  if (!json.containsKey(key)) {
    return false;
  }
  final value = json[key];
  if (value is! bool) {
    _reject(key, 'a boolean');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> json) {
  const key = 'tags';
  if (!json.containsKey(key)) {
    return const [];
  }
  final value = json[key];
  if (value is! List<Object?>) {
    _reject(key, 'a list of strings');
  }
  final tags = <String>[];
  for (final tag in value) {
    if (tag is! String) {
      _reject(key, 'a list of strings');
    }
    if (tag.isEmpty) {
      _reject(key, 'a list of non-empty strings');
    }
    tags.add(tag);
  }
  return tags;
}

String _readLocale(Map<String, Object?> json) {
  const key = 'locale';
  if (!json.containsKey(key)) {
    return 'en';
  }
  final value = json[key];
  if (value is! String) {
    _reject(key, 'a string');
  }
  if (!_localePattern.hasMatch(value)) {
    _reject(key, 'a language code such as en or de_DE');
  }
  return value;
}

import 'dart:async';

import 'package:flutter/material.dart';

class CountdownController extends ChangeNotifier {
  new({required this._duration}) : _remaining = _duration;

  static const _tick = Duration(seconds: 1);

  final Duration _duration;
  Duration _remaining;
  Timer? _timer;

  Duration get remaining => _remaining;

  bool get isRunning => _timer != null;

  void start() {
    if (isRunning || _remaining <= Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, _onTick);
    notifyListeners();
  }

  void pause() {
    if (!isRunning) {
      return;
    }
    _cancel();
    notifyListeners();
  }

  void reset() {
    _cancel();
    _remaining = _duration;
    notifyListeners();
  }

  void addTime(Duration extra) {
    if (extra <= Duration.zero) {
      throw ArgumentError.value(extra, 'extra', 'must be greater than zero');
    }
    _remaining += extra;
    notifyListeners();
  }

  @override
  void dispose() {
    _cancel();
    super.dispose();
  }

  void _cancel() {
    _timer?.cancel();
    _timer = null;
  }

  void _onTick(Timer timer) {
    final next = _remaining - _tick;
    _remaining = next > Duration.zero ? next : Duration.zero;
    if (_remaining <= Duration.zero) {
      _cancel();
    }
    notifyListeners();
  }
}

class CountdownTimer extends StatefulWidget {
  const new({required this.controller, super.key, this.onFinished});

  final CountdownController controller;
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  static const _bonus = Duration(seconds: 10);

  var _finished = false;

  @override
  void initState() {
    super.initState();
    _finished = widget.controller.remaining <= Duration.zero;
    widget.controller.addListener(_handleChange);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleChange);
      _finished = widget.controller.remaining <= Duration.zero;
      widget.controller.addListener(_handleChange);
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleChange);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => ListenableBuilder(
    listenable: widget.controller,
    builder: (context, child) => Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Text(_formatted(widget.controller.remaining)),
        Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            TextButton(
              onPressed: widget.controller.start,
              child: const Text('Start'),
            ),
            TextButton(
              onPressed: widget.controller.pause,
              child: const Text('Pause'),
            ),
            TextButton(
              onPressed: widget.controller.reset,
              child: const Text('Reset'),
            ),
            TextButton(
              onPressed: () => widget.controller.addTime(_bonus),
              child: const Text('+10s'),
            ),
          ],
        ),
      ],
    ),
  );

  String _formatted(Duration remaining) {
    final minutes = remaining.inMinutes.toString().padLeft(2, '0');
    final seconds = (remaining.inSeconds % 60).toString().padLeft(2, '0');
    return '$minutes:$seconds';
  }

  void _handleChange() {
    if (widget.controller.remaining > Duration.zero) {
      _finished = false;
      return;
    }
    if (_finished) {
      return;
    }
    _finished = true;
    widget.onFinished?.call();
  }
}

import 'dart:async';

import 'package:flutter/foundation.dart';

typedef SearchFetcher = Future<List<String>> Function(String query);

enum SearchStatus { idle, loading, success, error }

class SearchModel extends ChangeNotifier {
  new({
    required this._fetcher,
    this._debounce = const Duration(milliseconds: 300),
  });

  final SearchFetcher _fetcher;
  final Duration _debounce;

  var _status = SearchStatus.idle;
  var _query = '';
  var _results = const <String>[];
  Object? _error;
  Timer? _debounceTimer;

  // Identifies the query a response belongs to. Every query change bumps it,
  // so a response whose id no longer matches is stale and is dropped.
  var _queryId = 0;
  var _isDisposed = false;

  SearchStatus get status => _status;

  String get query => _query;

  List<String> get results => _results;

  Object? get error => _error;

  void onQueryChanged(String text) {
    if (_isDisposed || text == _query) {
      return;
    }
    _query = text;
    _queryId++;
    _debounceTimer?.cancel();
    _debounceTimer = null;
    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const [];
      _error = null;
    } else {
      _debounceTimer = Timer(_debounce, () => _startFetch(text));
    }
    notifyListeners();
  }

  /// Re-runs the fetch for the current query, skipping the debounce. Does
  /// nothing unless the last fetch failed.
  void retry() {
    if (_isDisposed || _status != SearchStatus.error) {
      return;
    }
    // A debounce may be pending for a query typed since the failure; the
    // retry takes its place so the query is fetched exactly once.
    _debounceTimer?.cancel();
    _startFetch(_query);
  }

  @override
  void dispose() {
    _isDisposed = true;
    _debounceTimer?.cancel();
    _debounceTimer = null;
    super.dispose();
  }

  void _startFetch(String text) {
    _debounceTimer = null;
    if (_isDisposed) {
      return;
    }
    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();
    unawaited(_fetch(_queryId, text));
  }

  Future<void> _fetch(int queryId, String text) async {
    try {
      final values = await _fetcher(text);
      if (_isDisposed || queryId != _queryId) {
        return;
      }
      _status = SearchStatus.success;
      _results = List<String>.unmodifiable(values);
      _error = null;
    } on Object catch (error) {
      if (_isDisposed || queryId != _queryId) {
        return;
      }
      _status = SearchStatus.error;
      _results = const [];
      _error = error;
    }
    notifyListeners();
  }
}

